#!/usr/bin/env python3
r"""Paired failure-mechanism audit of the selected Jev profile on the fresh Stage-2 tasks -- DESCRIPTIVE / POST HOC
(docs/REVIEW_ROUND12.md §3 #1, P1-1). Mechanical and reproducible: no subjective annotation; every field below is a
function of the logged episodes and of the task generator. Stage 1 and Stage 2 registered analyses are untouched.

    python scripts/stage2_failure_audit.py
    # reads runs/stage2_jevgym/{jevagent_best,best_single,llm_only}.jsonl, configs/eval/jevgym_stage2_tasks.json
    # (tasks regenerated by bench/suites/jevgym.py: family, clarify variant, canonical plan shape, free-text arguments;
    # no episode runs, no model is called) and results/stage2/stage2.json (the registered failure count);
    # writes results/stage2/failure_audit.{json,md}, results/stage2/failure_audit_cases.md and
    # paper/generated/failure_audit.tex (\defres{audit/...})

**Audited episodes (rule fixed in code before any trajectory is read).**

1. *Failures*: every expected task whose latest ``jevagent_best`` record is error-free and unsuccessful (the count must
   equal the registered ``intervention.jevagent_best.failures``), and the same seeds under ``best_single`` (the
   cascade alone) and ``llm_only``.
2. *Matched successes* of ``jevagent_best``, one per failure: failures in seed order; the candidates are the
   successful tasks with the same family and the same canonical plan shape (the tool-name sequence of the generator's
   gold plan), not a failure and not matched before; the nearest seed wins, ties to the lower seed; with no candidate
   of the same shape, the same family (flagged). Only the generator and ``jevagent_best``'s success flag are used, never
   a trajectory. The same seeds under ``best_single`` are read too.

**Per-episode fields** (step numbers are 0-based in the JSON, 1-based in the paper):

* ``first_div``: the first step whose executed tool is not in the oracle's acceptable set for that state (the
  ``tool_select`` DecisionLog's ``gold_aux.acceptable_tools`` when its gold status is ``ok``, else the step's
  ``oracle_tool``), or whose observation reports an irreversible error (an acceptable tool with disallowed
  arguments). ``div_kind`` = tool | arguments.
* ``div_by``: who chose the diverging action -- ``s1_tool`` (an accepted System-1 tool choice), ``s1_arg`` (an
  acceptable tool with an accepted System-1 argument that disagrees with its gold value), ``llm`` (the LLM chose it:
  a deferred or unasked tool choice).
* ``s1_err``: accepted System-1 decisions at or before ``first_div`` (all steps when there is none) that disagree with
  gold: tool (outside the acceptable set) and argument (value != gold, gold status ``ok``) counts and steps.
* ``fatal``: the step and decider of the call that ended the episode (strict mode), if any.
* Reflection trigger (profile only): fire steps; ``fired_before_div`` (a reflection was written at a step <=
  ``first_div``: it precedes the action at its own step).
* Paired split (profile vs cascade alone, same seed): ``split`` = the first step at which the two executed actions
  differ (tool name, or a non-free-text argument; free-text arguments such as a question's wording are ignored, their
  differences recorded). Before it both arms saw the same states. ``vs_cascade`` = ``split_after_reflection`` (a
  reflection had been written in the profile at a step <= ``split``), ``split_before_reflection``, ``no_split``,
  ``no_reflection_split``, ``no_reflection_no_split`` (the trigger never fired). At the split: each arm's decider and System-1's proposed tool and confidence, and the threshold.
* ``premature_finish``: the diverging action is the final ``finish``. ``termination``: ``strict_irreversible``
  (an irreversible call ended the episode), ``strict_side_effect``, ``budget`` (max steps without finishing),
  ``finished``.
* ``label`` (failures and successes alike; first match): ``premature finish``; ``accepted System-1 tool choice`` /
  ``accepted System-1 argument`` / ``LLM choice`` + `` after a reflection`` or `` without a prior reflection`` (arms
  without a trigger: no suffix); ``no divergence`` (successes); ``unclear / multiple`` (a failure without a divergent
  step, or a diverging step with both an accepted System-1 error and an LLM choice).

The sequence is called *consistent* only if every failure has the same label and every failure's paths split from
the cascade alone's after a reflection; the generated text then says "consistent with" and otherwise "these counts do
not identify how the failures arose". Base rates over all expected tasks (the trigger fired in most tasks) are
reported beside the audited counts. Nothing here says that the trigger caused a failure."""
from __future__ import annotations

import argparse
import datetime as dt
import hashlib
import json
import math
import re
import subprocess
import sys
from collections import Counter
from pathlib import Path
from typing import Any, Callable, Mapping, Sequence

import numpy as np

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "src"))

RUN = ROOT / "runs/stage2_jevgym"
TASKS = ROOT / "configs/eval/jevgym_stage2_tasks.json"
STAGE2_JSON = ROOT / "results/stage2/stage2.json"
OUT_DIR = ROOT / "results/stage2"
TEX_OUT = ROOT / "paper/generated/failure_audit.tex"
PROFILE, CASCADE, LLM = "jevagent_best", "best_single", "llm_only"
LABEL = "descriptive, post hoc (review round 12); mechanical rules fixed in code; not a registered analysis"
SEED_RE = re.compile(r"-(\d+)-")
IRREVERSIBLE = "Irreversible error"


class AuditError(RuntimeError):
    pass


# ====================================================================================== inputs
def _sha256(path: Path) -> str:
    h = hashlib.sha256()
    with path.open("rb") as f:
        for chunk in iter(lambda: f.read(1 << 20), b""):
            h.update(chunk)
    return h.hexdigest()


def _rel(p: Path | str) -> str:
    try:
        return str(Path(p).resolve().relative_to(ROOT))
    except ValueError:
        return str(p)


def load_latest(path: Path) -> dict[str, dict[str, Any]]:
    """task id -> latest record (file order), as scripts/primaries.load_arm."""
    out: dict[str, dict[str, Any]] = {}
    with path.open() as f:
        for line in f:
            if not line.strip():
                continue
            try:
                r = json.loads(line)
            except json.JSONDecodeError:
                continue
            if "task_id" in r:
                out[str(r["task_id"])] = r
    return out


def seed_of(task_id: str) -> int:
    m = SEED_RE.search(task_id)
    if not m:
        raise AuditError(f"no seed in task id {task_id!r}")
    return int(m.group(1))


def task_meta(frozen: Mapping[str, Any]) -> dict[str, dict[str, Any]]:
    """task id -> {family, variant, shape, free_args} from the generator (task generation only)."""
    from jevharness.bench.suites import load_suite
    from jevharness.harness.tools import finish_tool, param_kind_table

    suite = dict(frozen["suite"])
    facs = load_suite(suite.pop("name"), **suite)
    out: dict[str, dict[str, Any]] = {}
    for f, tid in zip(facs, frozen["task_ids"]):
        e = f()
        if e.task_id != tid:
            raise AuditError("the generator no longer reproduces the frozen task list")
        shape = " > ".join(t for t, _ in e._plan())
        e.reset()
        kinds = param_kind_table(list(e.tools()) + [finish_tool()], getattr(e, "param_kinds", None))
        out[tid] = {"family": e.family, "variant": getattr(e, "variant", None), "shape": shape,
                    "free_args": sorted(k for k, v in kinds.items() if v == "free")}
    return out


# ====================================================================================== per-episode fields
def _decisions(step: Mapping[str, Any], dp: str) -> list[Mapping[str, Any]]:
    return [d for d in step.get("decisions") or [] if d.get("dp") == dp and not d.get("shadow")]


def accepted(d: Mapping[str, Any]) -> bool:
    """System-1's answer was executed without the LLM (metrics.is_delegated)."""
    return d.get("mode") in ("replace", "cascade") and not d.get("deferred") and d.get("s1_value") is not None


def acceptable_tools(step: Mapping[str, Any]) -> list[str] | None:
    for d in _decisions(step, "tool_select"):
        if d.get("gold_status") == "ok":
            acc = (d.get("gold_aux") or {}).get("acceptable_tools")
            if acc:
                return list(acc)
            if d.get("gold") is not None:
                return [str(d["gold"])]
    return [str(step["oracle_tool"])] if step.get("oracle_tool") else None


def _irreversible(step: Mapping[str, Any]) -> bool:
    return str(step.get("observation") or "").startswith(IRREVERSIBLE)


def s1_errors(step: Mapping[str, Any]) -> dict[str, list[str]]:
    """Accepted System-1 decisions of one step that disagree with gold: tool choices outside the acceptable set and
    argument values != their gold value (gold status ok)."""
    out: dict[str, list[str]] = {"tool": [], "arg": []}
    acc = acceptable_tools(step)
    for d in _decisions(step, "tool_select"):
        if accepted(d) and d.get("gold_status") == "ok" and acc is not None and d.get("final_value") not in acc:
            out["tool"].append(str(d.get("final_value")))
    for d in _decisions(step, "tool_params"):
        if accepted(d) and d.get("gold_status") == "ok" and d.get("gold") is not None \
                and str(d.get("final_value")) != str(d.get("gold")):
            out["arg"].append(str(d.get("question"))[:80])
    return out


def tool_decider(step: Mapping[str, Any]) -> str:
    ts = _decisions(step, "tool_select")
    return "s1" if ts and accepted(ts[0]) else "llm"


def s1_view(step: Mapping[str, Any]) -> dict[str, Any] | None:
    """System-1's proposed tool and confidence at a step, and whether it was accepted."""
    ts = [d for d in _decisions(step, "tool_select") if d.get("s1_value") is not None]
    if not ts:
        return None
    d = ts[0]
    return {"tool": d.get("s1_value"), "conf": d.get("s1_conf"), "accepted": accepted(d),
            "final": d.get("final_value")}


def _action_key(step: Mapping[str, Any], free: set[str]) -> tuple[str, str, str]:
    """(tool, non-free-text args as canonical JSON, free-text args as canonical JSON)."""
    tool = str(step.get("tool"))
    args = step.get("args") if isinstance(step.get("args"), dict) else {}
    hard = {k: v for k, v in args.items() if f"{tool}.{k}" not in free}
    soft = {k: v for k, v in args.items() if f"{tool}.{k}" in free}
    return tool, json.dumps(hard, sort_keys=True, default=str), json.dumps(soft, sort_keys=True, default=str)


def termination(ep: Mapping[str, Any], max_steps: int) -> str:
    res = ep.get("result") or {}
    steps = ep.get("steps") or []
    if res.get("irreversible_error"):
        return "strict_irreversible"
    if (res.get("side_effects") or 0) > 0:
        return "strict_side_effect"
    if steps and steps[-1].get("tool") == "finish":
        return "finished"
    if len(steps) >= max_steps:
        return "budget"
    return "other"


def episode_fields(ep: Mapping[str, Any], free: set[str], trigger: bool) -> dict[str, Any]:
    steps = ep.get("steps") or []
    max_steps = int(((ep.get("meta") or {}).get("config") or {}).get("max_steps") or 30)
    f: dict[str, Any] = {"success": bool((ep.get("result") or {}).get("success")), "n_steps": len(steps),
                         "termination": termination(ep, max_steps), "first_div": None, "div_kind": None,
                         "div_tool": None, "div_canonical": None, "div_by": None, "premature_finish": False,
                         "fatal": None}
    for s in steps:
        acc = acceptable_tools(s)
        off_tool = acc is not None and s.get("tool") not in acc
        if off_tool or _irreversible(s):
            err = s1_errors(s)
            f.update({"first_div": int(s["step"]), "div_kind": "tool" if off_tool else "arguments",
                      "div_tool": s.get("tool"), "div_canonical": s.get("oracle_tool"), "div_acceptable": acc})
            dec = tool_decider(s)
            if off_tool:
                f["div_by"] = "s1_tool" if dec == "s1" else "llm"
            else:
                f["div_by"] = "s1_arg" if err["arg"] else "llm"
            f["div_mixed"] = bool(off_tool and dec == "llm" and err["arg"])
            f["premature_finish"] = bool(off_tool and s.get("tool") == "finish")
            break
    upto = f["first_div"] if f["first_div"] is not None else (len(steps) - 1)
    errs = {"tool": [], "arg": []}
    for s in steps:
        if int(s["step"]) > upto:
            break
        e = s1_errors(s)
        errs["tool"] += [int(s["step"])] * len(e["tool"])
        errs["arg"] += [int(s["step"])] * len(e["arg"])
    f["s1_err_tool_steps"], f["s1_err_arg_steps"] = errs["tool"], errs["arg"]
    for s in steps:
        if _irreversible(s):
            e = s1_errors(s)
            f["fatal"] = {"step": int(s["step"]), "tool": s.get("tool"),
                          "by": "s1_tool" if (tool_decider(s) == "s1" and e["tool"]) else
                          ("s1_arg" if e["arg"] else ("s1_tool" if tool_decider(s) == "s1" else "llm"))}
            break
    if trigger:
        fires = [int(s["step"]) for s in steps for d in _decisions(s, "reflection") if d.get("final_value") is True]
        f["fires"] = fires
        f["fired_before_div"] = bool(f["first_div"] is not None and fires and min(fires) <= f["first_div"])
    return f


def split_fields(prof: Mapping[str, Any], casc: Mapping[str, Any], free: set[str]) -> dict[str, Any]:
    """The first step at which the profile's and the cascade alone's executed actions differ (same seed)."""
    ps, cs = prof.get("steps") or [], casc.get("steps") or []
    fires = [int(s["step"]) for s in ps for d in _decisions(s, "reflection") if d.get("final_value") is True]
    out: dict[str, Any] = {"split": None, "free_text_diffs": [], "first_fire": min(fires) if fires else None}
    for i in range(min(len(ps), len(cs))):
        a, b = _action_key(ps[i], free), _action_key(cs[i], free)
        if a[:2] != b[:2]:
            out["split"] = i
            out["split_kind"] = "tool" if a[0] != b[0] else "arguments"
            break
        if a[2] != b[2]:
            out["free_text_diffs"].append(i)
    else:
        if len(ps) != len(cs):
            out["split"] = min(len(ps), len(cs))
            out["split_kind"] = "length"
    if out["split"] is None:
        out["vs_cascade"] = "no_split" if fires else "no_reflection_no_split"
    elif not fires:
        out["vs_cascade"] = "no_reflection_split"
    elif min(fires) <= out["split"]:
        out["vs_cascade"] = "split_after_reflection"
    else:
        out["vs_cascade"] = "split_before_reflection"
    k = out["split"]
    if k is not None and k < len(ps) and k < len(cs):
        out["at_split"] = {"profile": {"tool": ps[k].get("tool"), "by": tool_decider(ps[k]), "s1": s1_view(ps[k])},
                           "cascade": {"tool": cs[k].get("tool"), "by": tool_decider(cs[k]), "s1": s1_view(cs[k])},
                           "fires_up_to_split": sum(1 for x in fires if x <= k)}
    return out


def label_of(f: Mapping[str, Any], trigger: bool) -> str:
    if f["first_div"] is None:
        return "no divergence" if f["success"] else "unclear / multiple"
    if f.get("div_mixed"):
        return "unclear / multiple"
    if f["premature_finish"]:
        return "premature finish"
    base = {"s1_tool": "accepted System-1 tool choice", "s1_arg": "accepted System-1 argument",
            "llm": "LLM choice"}[f["div_by"]]
    if not trigger:
        return base
    return base + (" after a reflection" if f.get("fired_before_div") else " without a prior reflection")


# ====================================================================================== matching
def match_successes(failures: Sequence[str], successes: Sequence[str],
                    meta: Mapping[str, Mapping[str, Any]]) -> list[dict[str, Any]]:
    """One matched success per failure (failures in seed order): same family and plan shape, nearest seed (ties to
    the lower seed), without replacement; fallback: same family (flagged)."""
    used: set[str] = set()
    out = []
    for f in sorted(failures, key=seed_of):
        sf = seed_of(f)
        pools = [("family+shape", [t for t in successes if t not in used and meta[t]["family"] == meta[f]["family"]
                                   and meta[t]["shape"] == meta[f]["shape"]]),
                 ("family", [t for t in successes if t not in used and meta[t]["family"] == meta[f]["family"]])]
        for how, pool in pools:
            if pool:
                m = min(pool, key=lambda t: (abs(seed_of(t) - sf), seed_of(t)))
                used.add(m)
                out.append({"failure": f, "match": m, "rule": how, "seed_gap": seed_of(m) - sf})
                break
        else:
            raise AuditError(f"no matched success for {f}")
    return out


# ====================================================================================== the audit
def audit(run: Path, tasks_path: Path, stage2_json: Path | None,
          meta_fn: Callable[[Mapping[str, Any]], dict[str, dict[str, Any]]] = task_meta) -> dict[str, Any]:
    frozen = json.loads(tasks_path.read_text())
    exp = list(frozen["task_ids"])
    arms = {a: load_latest(run / f"{a}.jsonl") for a in (PROFILE, CASCADE, LLM)}
    for a, recs in arms.items():
        missing = [t for t in exp if t not in recs]
        if missing:
            raise AuditError(f"{a}: {len(missing)} expected task(s) without a record")
    meta = meta_fn(frozen)
    P = arms[PROFILE]
    ok = [t for t in exp if not P[t].get("error")]
    failures = [t for t in ok if not (P[t].get("result") or {}).get("success")]
    successes = [t for t in ok if (P[t].get("result") or {}).get("success")]
    reg_fail = reg_fired = reg_tasks = None
    if stage2_json is not None and stage2_json.exists():     # the registered intervention counts (A7.16 (d))
        iv = (json.loads(stage2_json.read_text()).get("descriptive") or {}).get("intervention") or {}
        reg_fail = (iv.get("jev_profile_failures") or {}).get("n")
        reg_fired = (iv.get("jev_profile_failures") or {}).get("with_trigger_fired")
        reg_tasks = ((iv.get("arms") or {}).get(PROFILE) or {}).get("trigger_tasks")
        if reg_fail is None:
            raise AuditError(f"{_rel(stage2_json)}: no registered failure count")
        if int(reg_fail) != len(failures):
            raise AuditError(f"{len(failures)} failures recomputed, {reg_fail} registered")
    matches = match_successes(failures, successes, meta)
    tau = ((P[exp[0]].get("meta") or {}).get("config") or {}).get("tool_select", {}).get("tau")

    def fields(t: str, arm: str) -> dict[str, Any]:
        free = set(meta[t]["free_args"])
        f = episode_fields(arms[arm][t], free, trigger=(arm == PROFILE))
        f["label"] = label_of(f, trigger=(arm == PROFILE))
        if arm == PROFILE:
            f.update(split_fields(arms[PROFILE][t], arms[CASCADE][t], free))
        return {"task": t, "seed": seed_of(t), "arm": arm, **meta_short(meta[t]), **f}

    groups: dict[str, list[dict[str, Any]]] = {
        "fail": [fields(t, PROFILE) for t in sorted(failures, key=seed_of)],
        "fail_cascade": [fields(t, CASCADE) for t in sorted(failures, key=seed_of)],
        "fail_llm": [fields(t, LLM) for t in sorted(failures, key=seed_of)],
        "match": [fields(m["match"], PROFILE) for m in matches],
        "match_cascade": [fields(m["match"], CASCADE) for m in matches],
        "success_all": [fields(t, PROFILE) for t in sorted(successes, key=seed_of)],
    }
    # base rates over every expected task (paired split vs the cascade alone; the trigger's activity)
    base: dict[str, Counter] = {"fail": Counter(), "success": Counter()}
    for t in ok:
        sf = split_fields(P[t], arms[CASCADE][t], set(meta[t]["free_args"]))
        base["success" if (P[t].get("result") or {}).get("success") else "fail"][sf["vs_cascade"]] += 1
    summary = {g: summarise(rows, trigger=g in ("fail", "match", "success_all")) for g, rows in groups.items()}
    fired_tasks = summary["fail"]["fired_any"] + summary["success_all"]["fired_any"]
    for what, mine, reg in (("failures with a trigger fire", summary["fail"]["fired_any"], reg_fired),
                            ("tasks with a trigger fire", fired_tasks, reg_tasks)):
        if reg is not None and int(reg) != int(mine):
            raise AuditError(f"{what}: {mine} recomputed, {reg} registered")
    fl = groups["fail"]
    consistent = bool(fl) and len({r["label"] for r in fl}) == 1 and all(
        r.get("vs_cascade") == "split_after_reflection" for r in fl)
    res = {"label": LABEL, "tau_tool_select": tau, "n_expected": len(exp), "n_ok": len(ok),
           "n_failures": len(failures), "registered": {"failures": reg_fail, "failures_fired": reg_fired,
                                                       "trigger_tasks": reg_tasks},
           "matches": matches, "groups": groups,
           "summary": summary, "base_rates": {k: dict(v) for k, v in base.items()},
           "base_n": {"fail": sum(base["fail"].values()), "success": sum(base["success"].values())},
           "consistent": consistent,
           "reading": ("the failures share one mechanical sequence, which is consistent with, but does not establish, a "
                       "mechanism" if consistent else "these counts do not identify how the failures arose"),
           "cases": cases(groups, arms, tau),
           "provenance": {"run": _rel(run), "tasks": {"path": _rel(tasks_path), "sha256": _sha256(tasks_path)},
                          "arms": {a: {"path": _rel(run / f"{a}.jsonl"), "sha256": _sha256(run / f"{a}.jsonl")}
                                   for a in arms},
                          "registered": _rel(stage2_json) if stage2_json else None},
           "meta": {"generated": dt.datetime.now(dt.timezone.utc).isoformat(timespec="seconds"), "git": _git_head()}}
    return res


def meta_short(m: Mapping[str, Any]) -> dict[str, Any]:
    return {"family": m["family"], "variant": m["variant"], "shape": m["shape"]}


def summarise(rows: Sequence[Mapping[str, Any]], trigger: bool) -> dict[str, Any]:
    n = len(rows)
    div = [r for r in rows if r["first_div"] is not None]
    s: dict[str, Any] = {
        "n": n, "success": sum(r["success"] for r in rows), "diverged": len(div),
        "div_step_median": float(np.median([r["first_div"] for r in div])) + 1 if div else None,   # 1-based
        "div_by_s1_tool": sum(r["div_by"] == "s1_tool" for r in div),
        "div_by_s1_arg": sum(r["div_by"] == "s1_arg" for r in div),
        "div_by_llm": sum(r["div_by"] == "llm" for r in div),
        "s1_err_tool": sum(bool(r["s1_err_tool_steps"]) for r in rows),
        "s1_err_arg": sum(bool(r["s1_err_arg_steps"]) for r in rows),
        "s1_err_any": sum(bool(r["s1_err_tool_steps"] or r["s1_err_arg_steps"]) for r in rows),
        "premature_finish": sum(r["premature_finish"] for r in rows),
        "term_strict": sum(r["termination"].startswith("strict") for r in rows),
        "term_budget": sum(r["termination"] == "budget" for r in rows),
        "term_finished": sum(r["termination"] == "finished" for r in rows),
        "fatal_by_s1": sum(bool(r["fatal"]) and r["fatal"]["by"].startswith("s1") for r in rows),
        "fatal_by_llm": sum(bool(r["fatal"]) and r["fatal"]["by"] == "llm" for r in rows),
        "fatal_tools": dict(Counter(r["fatal"]["tool"] for r in rows if r["fatal"])),
        "labels": dict(Counter(r["label"] for r in rows)),
        "unclear": sum(r["label"] == "unclear / multiple" for r in rows),
        "families": dict(Counter(r["family"] for r in rows)),
    }
    if trigger:
        s.update({"fired_any": sum(bool(r["fires"]) for r in rows),
                  "fired_before_div": sum(r["fired_before_div"] for r in rows),
                  "split_after_reflection": sum(r["vs_cascade"] == "split_after_reflection" for r in rows),
                  "split_before_reflection": sum(r["vs_cascade"] == "split_before_reflection" for r in rows),
                  "no_split": sum(r["vs_cascade"] == "no_split" for r in rows),
                  "no_reflection": sum(r["vs_cascade"].startswith("no_reflection") for r in rows),
                  "no_reflection_split": sum(r["vs_cascade"] == "no_reflection_split" for r in rows),
                  "split_s1_same_tool": sum(1 for r in rows if (r.get("at_split") or {}).get("profile", {}).get("s1")
                                            and (r["at_split"].get("cascade") or {}).get("s1")
                                            and r["at_split"]["profile"]["s1"]["tool"] ==
                                            r["at_split"]["cascade"]["s1"]["tool"]),
                  "split_accept_flip": sum(1 for r in rows if (r.get("at_split") or {}).get("profile", {}).get("s1")
                                           and (r["at_split"].get("cascade") or {}).get("s1")
                                           and r["at_split"]["profile"]["s1"]["accepted"] !=
                                           r["at_split"]["cascade"]["s1"]["accepted"])})
    return s


# ====================================================================================== worked cases
def _case_steps(ep: Mapping[str, Any], upto: int) -> list[dict[str, Any]]:
    out = []
    for s in (ep.get("steps") or [])[: upto + 1]:
        v = s1_view(s)
        fired = any(d.get("final_value") is True for d in _decisions(s, "reflection"))
        out.append({"step": int(s["step"]) + 1, "tool": s.get("tool"), "by": tool_decider(s),
                    "s1_tool": (v or {}).get("tool"), "s1_conf": (v or {}).get("conf"),
                    "acceptable": acceptable_tools(s), "reflection": fired,
                    "irreversible": _irreversible(s)})
    return out


def cases(groups: Mapping[str, Sequence[Mapping[str, Any]]], arms: Mapping[str, Mapping[str, Any]],
          tau: Any) -> dict[str, Any]:
    """Two worked cases, selected mechanically: (1) the lowest-seed failure carrying the most frequent failure label
    whose same-seed cascade-alone episode succeeded; (2) a successful deferral: the failure case's matched success if
    it holds a deferred tool choice whose System-1 proposal was outside the acceptable set while the executed (LLM)
    tool was inside it, else the lowest-seed matched success with one."""
    fl = groups["fail"]
    if not fl:
        return {}
    modal = Counter(r["label"] for r in fl).most_common(1)[0][0]
    casc = {r["task"]: r for r in groups["fail_cascade"]}
    cand = [r for r in fl if r["label"] == modal and casc[r["task"]]["success"]] or [r for r in fl if r["label"] == modal]
    c1 = min(cand, key=lambda r: r["seed"])
    k = c1["first_div"] if c1["first_div"] is not None else c1["n_steps"] - 1
    kk = max(k, c1.get("split") or 0)
    out: dict[str, Any] = {"failure": {"task": c1["task"], "seed": c1["seed"], "family": c1["family"],
                                       "variant": c1["variant"], "label": c1["label"], "modal_label": modal,
                                       "first_div": c1["first_div"], "split": c1.get("split"),
                                       "vs_cascade": c1.get("vs_cascade"), "at_split": c1.get("at_split"),
                                       "fires": c1.get("fires"), "termination": c1["termination"],
                                       "profile_steps": _case_steps(arms[PROFILE][c1["task"]], k),
                                       "cascade_steps": _case_steps(arms[CASCADE][c1["task"]], kk + 1),
                                       "cascade_success": casc[c1["task"]]["success"],
                                       "llm_success": next(r["success"] for r in groups["fail_llm"]
                                                           if r["task"] == c1["task"])},
                           "tau": tau}

    def deferral(t: str) -> dict[str, Any] | None:
        for s in arms[PROFILE][t].get("steps") or []:
            acc = acceptable_tools(s)
            for d in _decisions(s, "tool_select"):
                if d.get("deferred") and acc and d.get("s1_value") not in acc and s.get("tool") in acc:
                    return {"step": int(s["step"]), "s1_tool": d.get("s1_value"), "s1_conf": d.get("s1_conf"),
                            "llm_tool": s.get("tool"), "acceptable": acc}
        return None

    pair = next((m for m in groups["match"] if m["task"] == _match_of(groups, c1["task"])), None)
    order = ([pair] if pair else []) + sorted(groups["match"], key=lambda r: r["seed"])
    for r in order:
        d = deferral(r["task"])
        if d:
            out["deferral"] = {"task": r["task"], "seed": r["seed"], "family": r["family"], "variant": r["variant"],
                               "fires": r.get("fires"), "n_steps": r["n_steps"], **d,
                               "steps": _case_steps(arms[PROFILE][r["task"]], d["step"])}
            break
    return out


def _match_of(groups: Mapping[str, Sequence[Mapping[str, Any]]], failure: str) -> str | None:
    fl = [r["task"] for r in groups["fail"]]
    mt = [r["task"] for r in groups["match"]]
    return mt[fl.index(failure)] if failure in fl and len(mt) == len(fl) else None


def _git_head() -> str:
    try:
        return subprocess.run(["git", "rev-parse", "HEAD"], cwd=ROOT, capture_output=True, text=True,
                              check=True).stdout.strip()
    except Exception:  # noqa: BLE001
        return "unknown"


# ====================================================================================== reports
GROUP_NAMES = {"fail": "profile failures", "fail_cascade": "same seeds, cascade alone",
               "fail_llm": "same seeds, LLM-only", "match": "matched profile successes",
               "match_cascade": "matched seeds, cascade alone", "success_all": "all profile successes"}
ROWS = (("n", "episodes"), ("success", "successful"), ("diverged", "left the canonical plan"),
        ("div_step_median", "first divergent step (median, 1-based)"),
        ("div_by_s1_tool", "divergent action = accepted System-1 tool choice"),
        ("div_by_s1_arg", "divergent action = accepted System-1 argument"),
        ("div_by_llm", "divergent action = LLM choice"),
        ("s1_err_any", "accepted System-1 decision against gold at/before divergence"),
        ("s1_err_tool", "  of which a tool choice"), ("s1_err_arg", "  of which an argument"),
        ("fired_any", "trigger fired (any step)"), ("fired_before_div", "trigger fired at/before divergence"),
        ("split_after_reflection", "paths split from cascade alone after a reflection"),
        ("split_before_reflection", "paths split before any reflection"),
        ("no_split", "paths never split (trigger fired)"),
        ("no_reflection_split", "no reflection, paths split"),
        ("split_s1_same_tool", "at the split, System-1 proposed the same tool in both arms"),
        ("split_accept_flip", "at the split, System-1 accepted in one arm only"),
        ("premature_finish", "premature finish"), ("term_strict", "ended by strict mode (irreversible call)"),
        ("fatal_by_s1", "  irreversible call chosen by System-1 (accepted)"),
        ("fatal_by_llm", "  irreversible call chosen by the LLM"),
        ("term_budget", "ended by the step budget"), ("unclear", "unclear / multiple"))


def to_markdown(res: Mapping[str, Any]) -> str:
    S = res["summary"]
    gs = list(GROUP_NAMES)
    L = ["# Stage 2: paired failure-mechanism audit of the Jev profile (descriptive, post hoc)", "",
         f"Label: {res['label']}. {res['n_failures']} failures of `{PROFILE}` among {res['n_ok']} tasks "
         f"(registered: {res['registered']}); {len(res['matches'])} matched successes (same family and plan "
         f"shape, nearest seed). Threshold τ̂* (tool choice) = {res['tau_tool_select']}.", "",
         f"**Reading:** {res['reading']}.", "",
         "| quantity | " + " | ".join(GROUP_NAMES[g] for g in gs) + " |", "|---|" + "---|" * len(gs)]
    for k, name in ROWS:
        cells = []
        for g in gs:
            v = S[g].get(k)
            cells.append("–" if v is None else (f"{v:.1f}" if isinstance(v, float) else str(v)))
        L.append(f"| {name} | " + " | ".join(cells) + " |")
    L += ["", "Labels: " + "; ".join(f"{GROUP_NAMES[g]}: " + ", ".join(f"{k} {v}" for k, v in S[g]["labels"].items())
                                    for g in gs) + ".",
          "Fatal calls: " + "; ".join(f"{GROUP_NAMES[g]}: {S[g]['fatal_tools'] or 'none'}" for g in gs) + ".", "",
          f"Base rates over all {res['base_n']['success'] + res['base_n']['fail']} tasks (profile vs the cascade "
          f"alone, same seed): failures {res['base_rates']['fail']}; successes {res['base_rates']['success']}.", "",
          "## Episodes", "",
          "| group | task | variant | label | first div. (1-based) | div. tool / canonical | by | S1 errors (tool / arg steps) | "
          "fires (1-based) | split (1-based) | vs cascade | at split: profile S1 (conf, accepted) / cascade S1 | end |",
          "|---|---|---|---|---|---|---|---|---|---|---|---|---|"]
    for g in gs:
        if g == "success_all":
            continue
        for r in res["groups"][g]:
            asp = r.get("at_split") or {}

            def sv(x: Any) -> str:
                return "–" if not x else f"{x['tool']} ({x['conf']}, {'acc' if x['accepted'] else 'def'})"
            L.append(f"| {g} | `{r['task']}` | {r['variant'] or r['family']} | {r['label']} | "
                     f"{'' if r['first_div'] is None else r['first_div'] + 1} | {r['div_tool'] or ''} / "
                     f"{r['div_canonical'] or ''} | {r['div_by'] or ''} | "
                     f"{[x + 1 for x in r['s1_err_tool_steps']]} / {[x + 1 for x in r['s1_err_arg_steps']]} | "
                     f"{[x + 1 for x in r.get('fires', [])] if 'fires' in r else '–'} | "
                     f"{'' if r.get('split') is None else r['split'] + 1} | {r.get('vs_cascade', '–')} | "
                     f"{sv((asp.get('profile') or {}).get('s1'))} / {sv((asp.get('cascade') or {}).get('s1'))} | "
                     f"{r['termination']} |")
    L += ["", "Matches: " + "; ".join(f"`{m['failure']}` -> `{m['match']}` ({m['rule']}, seed gap {m['seed_gap']:+d})"
                                      for m in res["matches"]) + ".", "",
          f"Generated {res['meta']['generated']} at git {str(res['meta']['git'])[:12]}; inputs: "
          + ", ".join(f"`{v['path']}` ({v['sha256'][:12]})" for v in res["provenance"]["arms"].values()) + "."]
    return "\n".join(L) + "\n"


def _fmt_conf(x: Any) -> str:
    return "–" if x is None else f"{float(x):.2f}"


def cases_markdown(res: Mapping[str, Any]) -> str:
    c = res["cases"]
    f, d, tau = c.get("failure"), c.get("deferral"), c.get("tau")
    L = ["# Two worked cases from the failure audit (descriptive; facts from the logs)", "",
         f"Selected mechanically by scripts/stage2_failure_audit.py (rule in `cases`). Steps are 1-based. τ̂* for the "
         f"tool choice = {_fmt_conf(tau)}: System-1's tool is executed only when its confidence reaches it; otherwise "
         "the LLM chooses.", ""]
    if f:
        ps = f["profile_steps"]
        k = f["first_div"]
        div = ps[k] if k is not None and k < len(ps) else ps[-1]
        asp = f.get("at_split") or {}
        p1, c1 = (asp.get("profile") or {}).get("s1"), (asp.get("cascade") or {}).get("s1")
        fires = [x + 1 for x in (f.get("fires") or [])]
        L += [f"## Case 1: a failure of the Jev profile (`{f['task']}`, {f['family']}, variant {f['variant']})", "",
              f"- Mechanical label: *{f['label']}* (the most frequent label among the failures: *{f['modal_label']}*).",
              "- Steps of the profile up to the first divergence: "
              + "; ".join(f"{s['step']}. `{s['tool']}` by {'System-1 (accepted)' if s['by'] == 's1' else 'the LLM'}"
                          f"{' (System-1 proposed `' + str(s['s1_tool']) + '` at ' + _fmt_conf(s['s1_conf']) + ')' if s['by'] != 's1' and s['s1_tool'] else ''}"
                          f"{' at confidence ' + _fmt_conf(s['s1_conf']) if s['by'] == 's1' else ''}"
                          f"{'; a reflection was written before this action' if s['reflection'] else ''}"
                          f"{'; the call was irreversible and ended the episode (strict mode)' if s['irreversible'] else ''}"
                          for s in ps) + ".",
              f"- The oracle's acceptable tools at step {div['step']}: {', '.join(div['acceptable'] or [])}.",
              f"- The trigger fired at step(s) {fires or 'none'}.",
              f"- The same seed under the cascade alone (no trigger) {'succeeded' if f['cascade_success'] else 'failed'}; "
              f"under LLM-only it {'succeeded' if f['llm_success'] else 'failed'}."]
        if f.get("split") is not None and p1 and c1:
            L.append(f"- Both arms executed the same actions up to step {f['split']}; at step {f['split'] + 1} System-1 "
                     f"proposed `{p1['tool']}` at confidence {_fmt_conf(p1['conf'])} in the profile "
                     f"({'accepted' if p1['accepted'] else 'deferred'}) and `{c1['tool']}` at "
                     f"{_fmt_conf(c1['conf'])} in the cascade alone ({'accepted' if c1['accepted'] else 'deferred'}). "
                     f"In the profile, {asp.get('fires_up_to_split', 0)} reflection(s) had been written by then; they "
                     "are part of the state System-1 is shown.")
        L += ["- What this does and does not show: the logs fix the order of events above; they do not show what "
              "System-1 or the LLM would have done without the reflection text at the same state, so the case does "
              "not identify a cause.", ""]
    if d:
        L += [f"## Case 2: a successful deferral in the Jev profile (`{d['task']}`, {d['family']}, variant "
              f"{d['variant']})", "",
              f"- At step {d['step'] + 1}, System-1 proposed `{d['s1_tool']}` at confidence {_fmt_conf(d['s1_conf'])}, "
              f"below τ̂* = {_fmt_conf(tau)}, so the LLM chose; it called `{d['llm_tool']}`, which the oracle accepts "
              f"there (acceptable: {', '.join(d['acceptable'])}); `{d['s1_tool']}` is not.",
              f"- The episode succeeded in {d['n_steps']} steps; the trigger fired at step(s) "
              f"{[x + 1 for x in (d.get('fires') or [])] or 'none'}.",
              "- Facts only: the threshold sent this decision to the LLM, and the LLM's choice was on the canonical "
              "plan.", ""]
    L += [f"Overall reading of the audit: {res['reading']}."]
    return "\n".join(L) + "\n"


def _tex_rows(res: Mapping[str, Any]) -> dict[tuple[str, ...], tuple[str, Any]]:
    """``audit/<group>/<quantity>`` for the ROWS quantities and the label counts (``audit/<group>/label/<slug>``),
    ``audit/base/{fail,success}/<vs_cascade>`` and ``audit/base_n/...``, ``audit/n_failures``, ``audit/tau``,
    ``audit/consistent`` (yes / no) and the worked cases ``audit/case/{fail,defer}/...``."""
    rows: dict[tuple[str, ...], tuple[str, Any]] = {}

    def put(path: tuple[str, ...], kind: str, v: Any) -> None:
        if v is None or (isinstance(v, float) and not math.isfinite(v)):
            return
        rows[path] = (kind, v)

    for g, s in res["summary"].items():
        for k, _ in ROWS:
            if k in s:
                put(("audit", g, k), "f1" if k == "div_step_median" else "int", s[k])
        for lab, n in s["labels"].items():
            put(("audit", g, "label", slug(lab)), "int", n)
        for tool, n in s["fatal_tools"].items():
            put(("audit", g, "fatal_tool", slug(tool)), "int", n)
    for k in ("fail", "success"):
        for v, n in res["base_rates"][k].items():
            put(("audit", "base", k, v), "int", n)
        put(("audit", "base_n", k), "intc", res["base_n"][k])
    put(("audit", "n_failures"), "int", res["n_failures"])
    put(("audit", "tau"), "f2", res["tau_tool_select"])
    put(("audit", "consistent"), "text", "yes" if res["consistent"] else "no")
    put(("audit", "reading"), "text", res["reading"])
    c = res.get("cases") or {}
    f, d = c.get("failure"), c.get("deferral")
    if f:
        put(("audit", "case", "fail", "seed"), "int", f["seed"])
        put(("audit", "case", "fail", "variant"), "text", f["variant"] or f["family"])
        if f["first_div"] is not None:
            put(("audit", "case", "fail", "div_step"), "int", f["first_div"] + 1)
            put(("audit", "case", "fail", "div_tool"), "tool", f["profile_steps"][f["first_div"]]["tool"])
        asp = f.get("at_split") or {}
        if f.get("split") is not None:
            put(("audit", "case", "fail", "split_step"), "int", f["split"] + 1)
            for arm in ("profile", "cascade"):
                v = (asp.get(arm) or {}).get("s1")
                if v:
                    put(("audit", "case", "fail", arm, "s1_tool"), "tool", v["tool"])
                    put(("audit", "case", "fail", arm, "s1_conf"), "f2", v["conf"])
                    put(("audit", "case", "fail", arm, "accepted"), "text", "accepted" if v["accepted"] else "deferred")
        put(("audit", "case", "fail", "first_fire"), "int", (min(f["fires"]) + 1) if f.get("fires") else None)
    if d:
        put(("audit", "case", "defer", "seed"), "int", d["seed"])
        put(("audit", "case", "defer", "variant"), "text", d["variant"] or d["family"])
        put(("audit", "case", "defer", "step"), "int", d["step"] + 1)
        put(("audit", "case", "defer", "s1_tool"), "tool", d["s1_tool"])
        put(("audit", "case", "defer", "s1_conf"), "f2", d["s1_conf"])
        put(("audit", "case", "defer", "llm_tool"), "tool", d["llm_tool"])
        put(("audit", "case", "defer", "n_steps"), "int", d["n_steps"])
    return rows


def slug(s: str) -> str:
    return re.sub(r"[^a-z0-9]+", "_", s.lower()).strip("_")


def _fmt(kind: str, v: Any) -> str:
    if kind == "int":
        return f"{float(v):.0f}"
    if kind == "intc":
        return f"{float(v):,.0f}".replace(",", "{,}")
    if kind == "f1":
        return f"{float(v):.1f}"
    if kind == "f2":
        return f"{float(v):.2f}"
    if kind == "tool":
        return r"\texttt{" + str(v).replace("_", r"\_") + "}"
    return str(v).replace("_", r"\_").replace("%", r"\%").replace("&", r"\&")


def to_tex(res: Mapping[str, Any]) -> str:
    lines = ["% AUTO-GENERATED by scripts/stage2_failure_audit.py -- do not edit by hand.",
             f"% generated {res['meta']['generated']} at git {str(res['meta']['git'])[:12]}; {LABEL}",
             r"\makeatletter",
             r"\providecommand{\res}[1]{\ifcsname jevres@#1\endcsname\csname jevres@#1\endcsname\else\tbd\fi}",
             r"\providecommand{\defres}[2]{\expandafter\def\csname jevres@#1\endcsname{#2}}"]
    lines += [f"\\defres{{{'/'.join(p)}}}{{{_fmt(k, v)}}}" for p, (k, v) in sorted(_tex_rows(res).items())]
    lines += [r"\makeatother", ""]
    return "\n".join(lines)


def _jsonable(x: Any) -> Any:
    if isinstance(x, dict):
        return {str(k): _jsonable(v) for k, v in x.items()}
    if isinstance(x, (list, tuple)):
        return [_jsonable(v) for v in x]
    if isinstance(x, (np.floating, float)):
        return None if not math.isfinite(float(x)) else float(x)
    if isinstance(x, np.integer):
        return int(x)
    if isinstance(x, np.bool_):
        return bool(x)
    return x


def main(argv: Sequence[str] | None = None) -> int:
    ap = argparse.ArgumentParser(description=__doc__.split("\n\n")[0])
    ap.add_argument("--run", default=str(RUN))
    ap.add_argument("--tasks", default=str(TASKS))
    ap.add_argument("--stage2-json", default=str(STAGE2_JSON))
    ap.add_argument("--out", default=str(OUT_DIR))
    ap.add_argument("--tex", default=str(TEX_OUT))
    a = ap.parse_args(argv)
    try:
        res = audit(Path(a.run), Path(a.tasks), Path(a.stage2_json))
    except AuditError as e:
        print(f"[failure_audit] FAILED: {e}", file=sys.stderr)
        return 1
    out = Path(a.out)
    out.mkdir(parents=True, exist_ok=True)
    slim = {**res, "groups": {g: (rows if g != "success_all" else [r["task"] for r in rows])   # base-rate group:
                              for g, rows in res["groups"].items()}}                          # summary + task ids only
    (out / "failure_audit.json").write_text(json.dumps(_jsonable(slim), indent=1))
    (out / "failure_audit.md").write_text(to_markdown(res))
    (out / "failure_audit_cases.md").write_text(cases_markdown(res))
    if a.tex:
        Path(a.tex).parent.mkdir(parents=True, exist_ok=True)
        Path(a.tex).write_text(to_tex(res))
    S = res["summary"]
    print(f"[failure_audit] {res['n_failures']} failures; labels {S['fail']['labels']}; vs cascade: after reflection "
          f"{S['fail']['split_after_reflection']}, before {S['fail']['split_before_reflection']}, no split "
          f"{S['fail']['no_split']}; matched successes: after reflection {S['match']['split_after_reflection']}, "
          f"no split {S['match']['no_split']}; base {res['base_rates']}; consistent = {res['consistent']}",
          file=sys.stderr)
    return 0


if __name__ == "__main__":
    sys.exit(main())
